<div class="page-heading"><div><span class="eyebrow">Gestión</span><h1>Inventario</h1><p>Stock, lotes y movimientos.</p></div><button class="btn btn-primary" data-modal-open="move-create">＋ Movimiento</button></div><?php if($success):?><div class="alert alert-success"><?=e($success)?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><div class="cards-grid mb-1"><?php foreach($stock as $x):?><div class="soft-panel"><strong><?=e($x['producto'])?></strong><p><?=e($x['stock']??0)?> <?=e($x['simbolo'])?></p><small><?=e($x['inventario'])?></small></div><?php endforeach;?></div><section class="card"><div class="table-wrap"><table class="modern-table"><thead><tr><th>Fecha</th><th>Producto</th><th>Tipo</th><th>Cantidad</th><th>Usuario</th></tr></thead><tbody><?php foreach($movements as $m):?><tr><td><?=e($m['fecha_movimiento'])?></td><td><?=e($m['producto'])?></td><td><?=e($m['tipo'])?></td><td><?=e($m['cantidad'])?></td><td><?=e($m['usuario'])?></td></tr><?php endforeach;?></tbody></table></div></section><div class="modal" id="move-create"><div class="modal-backdrop"></div><div class="modal-dialog"><div class="modal-header"><h2>Movimiento</h2><button class="modal-close" data-modal-close>×</button></div><form method="POST" action="<?=url('/inventario/movimientos')?>"><?=csrf_field()?><div class="modal-body form-grid"><label><span>Inventario</span><select name="inventario_id"><?php foreach($inventories as $i):?><option value="<?=$i['id']?>"><?=e($i['nombre'])?></option><?php endforeach;?></select></label><label><span>Producto</span><select name="producto_id"><?php foreach($products as $p):?><option value="<?=$p['id']?>"><?=e($p['nombre'])?></option><?php endforeach;?></select></label><label><span>Tipo</span><select name="tipo_movimiento_id"><?php foreach($movementTypes as $t):?><option value="<?=$t['id']?>"><?=e($t['nombre'])?></option><?php endforeach;?></select></label><label><span>Cantidad</span><input type="number" step="any" name="cantidad" required></label><label class="field-full"><span>Observaciones</span><textarea name="observaciones"></textarea></label></div><div class="modal-footer"><button class="btn btn-primary">Guardar</button></div></form></div></div>
<div class="mt-1"><button class="btn btn-secondary" data-modal-open="product-create">＋ Nuevo producto</button></div>
<div class="modal" id="product-create"><div class="modal-backdrop"></div><div class="modal-dialog modal-lg"><div class="modal-header"><h2>Nuevo producto</h2><button class="modal-close" data-modal-close>×</button></div><form method="POST" action="<?=url('/inventario/productos')?>"><?=csrf_field()?><div class="modal-body form-grid"><label><span>Código</span><input name="codigo" required></label><label><span>Nombre</span><input name="nombre" required></label><label><span>Categoría</span><select name="categoria_producto_id"><option value="">Sin categoría</option><?php foreach($productCategories as $c):?><option value="<?=$c['id']?>"><?=e($c['nombre'])?></option><?php endforeach;?></select></label><label><span>Unidad base</span><select name="unidad_base_id" required><?php foreach($units as $u):?><option value="<?=$u['id']?>"><?=e($u['simbolo'].' · '.$u['nombre'])?></option><?php endforeach;?></select></label><label><span><input type="checkbox" name="controla_lote" value="1"> Controla lote</span></label><label><span><input type="checkbox" name="controla_vencimiento" value="1"> Controla vencimiento</span></label><label class="field-full"><span>Descripción</span><textarea name="descripcion"></textarea></label></div><div class="modal-footer"><button class="btn btn-primary">Crear producto</button></div></form></div></div>
